# Java: loops and number systems (60 problems, no patterns). Uses jq() from build-problems-java-core.py.
T = "Loops and numbers"
JN = [("int", "n")]
JL = [("long", "n")]
YN = "Print `Yes` or `No`."
ONE = "One integer."
jq("j-print-1-to-10", "Print 1 to 10", "EASY", T, "Print the numbers 1 to 10 on one line separated by spaces, with a `for` loop.", "There is no input.", "`1 2 ... 10`.", "None.",
   'StringBuilder sb = new StringBuilder();\nfor (int i = 1; i <= 10; i++) sb.append(i).append(i < 10 ? " " : "");\nSystem.out.println(sb);', [""], (), samples=1)
jq("j-print-10-to-1", "Count Down", "EASY", T, "Print 10 down to 1 on one line separated by spaces, with a `while` loop.", "There is no input.", "`10 9 ... 1`.", "None.",
   'int i = 10;\nStringBuilder sb = new StringBuilder();\nwhile (i >= 1) {\n    sb.append(i).append(i > 1 ? " " : "");\n    i--;\n}\nSystem.out.println(sb);', [""], (), samples=1)
jq("j-even-to-50", "Even Numbers up to 50", "EASY", T, "Print every even number from 1 to 50 on one line, separated by spaces.", "There is no input.", "`2 4 ... 50`.", "None.",
   'StringBuilder sb = new StringBuilder();\nfor (int i = 2; i <= 50; i += 2) sb.append(i).append(i < 50 ? " " : "");\nSystem.out.println(sb);', [""], (), samples=1)
jq("j-odd-to-50", "Odd Numbers up to 50", "EASY", T, "Print every odd number from 1 to 50 on one line, separated by spaces, with a `while` loop.", "There is no input.", "`1 3 ... 49`.", "None.",
   'int i = 1;\nStringBuilder sb = new StringBuilder();\nwhile (i <= 49) {\n    sb.append(i).append(i < 49 ? " " : "");\n    i += 2;\n}\nSystem.out.println(sb);', [""], (), samples=1)
jq("j-multiplication-table", "Multiplication Table", "EASY", T, "Read `n` and print its table from 1 to 10, one line each, like `5 x 3 = 15`.", ONE, "Ten lines.", "1 <= n <= 1000",
   'for (int i = 1; i <= 10; i++) System.out.println(n + " x " + i + " = " + n * i);', ["5", "12", "1", "100", "7"], JN)
jq("j-sum-natural", "Sum of the First N Numbers", "EASY", T, "Print `1 + 2 + ... + n` using a loop.", ONE, "The sum.", "1 <= n <= 100000",
   'long sum = 0;\nfor (int i = 1; i <= n; i++) sum += i;\nSystem.out.println(sum);', ["10", "1", "100", "100000", "37"], JN)
jq("j-factorial-loop", "Factorial", "EASY", T, "Print `n!` computed with a loop (`0! = 1`).", ONE, "The factorial.", "0 <= n <= 20",
   'long f = 1;\nfor (int i = 2; i <= n; i++) f *= i;\nSystem.out.println(f);', ["5", "0", "1", "10", "20"], JN)
jq("j-digit-counter", "Count the Digits", "EASY", T, "Print how many digits a non-negative integer has (`0` has one).", ONE, "The count.", "0 <= n <= 10^9",
   'int count = 0;\ndo {\n    count++;\n    n /= 10;\n} while (n > 0);\nSystem.out.println(count);', ["12345", "0", "7", "1000000000", "90"], JN)
jq("j-sum-of-digits", "Sum of Digits", "EASY", T, "Print the sum of the digits of `n`.", ONE, "The sum.", "0 <= n <= 10^9",
   'int sum = 0;\nwhile (n > 0) {\n    sum += n % 10;\n    n /= 10;\n}\nSystem.out.println(sum);', ["1234", "0", "9", "999999999", "1001"], JN)
jq("j-reverse-integer", "Reverse a Number", "EASY", T, "Print the digits of `n` reversed as a number (`1200` becomes `21`).", ONE, "The reversed number.", "0 <= n <= 10^9",
   'long rev = 0;\nwhile (n > 0) {\n    rev = rev * 10 + n % 10;\n    n /= 10;\n}\nSystem.out.println(rev);', ["1234", "1200", "0", "7", "987654321"], JN)
jq("j-palindrome-number", "Palindrome Number", "EASY", T, "A palindrome reads the same backwards. " + YN, ONE, "`Yes` or `No`.", "0 <= n <= 10^9",
   'int original = n;\nlong rev = 0;\nwhile (n > 0) {\n    rev = rev * 10 + n % 10;\n    n /= 10;\n}\nSystem.out.println(rev == original ? "Yes" : "No");', ["121", "123", "7", "1221", "10"], JN)
jq("j-armstrong-3", "Armstrong Number (3 digits)", "EASY", T, "A 3-digit number is an Armstrong number when the cubes of its digits add up to the number (153 = 1 + 125 + 27). " + YN, "One 3-digit integer.", "`Yes` or `No`.", "100 <= n <= 999",
   'int original = n, sum = 0;\nwhile (n > 0) {\n    int d = n % 10;\n    sum += d * d * d;\n    n /= 10;\n}\nSystem.out.println(sum == original ? "Yes" : "No");', ["153", "370", "123", "407", "999"], JN)
jq("j-prime-check", "Is It Prime?", "EASY", T, "Print `Prime` or `Not prime`. A prime has exactly two factors; 1 is not prime.", "One positive integer.", "`Prime` or `Not prime`.", "1 <= n <= 10^9",
   'boolean prime = n >= 2;\nfor (long i = 2; i * i <= n; i++) if (n % i == 0) { prime = false; break; }\nSystem.out.println(prime ? "Prime" : "Not prime");', ["2", "1", "17", "100", "999999937"], JN)
jq("j-primes-to-100", "Primes up to 100", "EASY", T, "Print all prime numbers from 1 to 100 on one line.", "There is no input.", "The primes separated by spaces.", "None.",
   'StringBuilder sb = new StringBuilder();\nfor (int n = 2; n <= 100; n++) {\n    boolean prime = true;\n    for (int i = 2; i * i <= n; i++) if (n % i == 0) { prime = false; break; }\n    if (prime) sb.append(sb.length() > 0 ? " " : "").append(n);\n}\nSystem.out.println(sb);', [""], (), samples=1)
jq("j-fibonacci", "Fibonacci Series", "EASY", T, "Print the first `n` Fibonacci numbers `0 1 1 2 3 5 ...` on one line.", ONE, "`n` numbers.", "1 <= n <= 60",
   'long a = 0, b = 1;\nStringBuilder sb = new StringBuilder();\nfor (int i = 0; i < n; i++) {\n    sb.append(a).append(i < n - 1 ? " " : "");\n    long t = a + b;\n    a = b;\n    b = t;\n}\nSystem.out.println(sb);', ["10", "1", "2", "20", "60"], JN)
jq("j-gcd", "GCD of Two Numbers", "EASY", T, "Print the greatest common divisor of two positive integers using the Euclidean method in a loop.", TWO if False else "One line: `a b`.", "The GCD.", "1 <= a, b <= 10^9",
   'while (b != 0) {\n    int t = a % b;\n    a = b;\n    b = t;\n}\nSystem.out.println(a);', ["12 18", "17 5", "100 75", "1 1", "1000000000 250000000"], [("int", "a b")])
jq("j-lcm", "LCM of Two Numbers", "EASY", T, "Print the least common multiple of two positive integers, using the GCD (`lcm = a / gcd * b`).", "One line: `a b`.", "The LCM.", "1 <= a, b <= 10^6",
   'long x = a, y = b;\nwhile (y != 0) {\n    long t = x % y;\n    x = y;\n    y = t;\n}\nSystem.out.println((long) a / x * b);', ["4 6", "7 5", "12 18", "1 1", "1000000 999999"], [("int", "a b")])
jq("j-power-loop", "Power with a Loop", "EASY", T, "Read `x` and `y` and print `x` raised to `y` by repeated multiplication (no `Math.pow`).", "One line: `x y`.", "The result.", "1 <= x <= 10, 0 <= y <= 15",
   'long r = 1;\nfor (int i = 0; i < y; i++) r *= x;\nSystem.out.println(r);', ["2 10", "5 0", "10 15", "3 4", "1 9"], [("int", "x y")])
jq("j-factors-printer", "Proper Divisors", "EASY", T, "Print all proper divisors of `n` (every factor except `n` itself) in increasing order on one line. For `n = 1` print `None`.", "One positive integer.", "The divisors, or `None`.", "1 <= n <= 100000",
   'StringBuilder sb = new StringBuilder();\nfor (int i = 1; i < n; i++) if (n % i == 0) sb.append(sb.length() > 0 ? " " : "").append(i);\nSystem.out.println(sb.length() > 0 ? sb.toString() : "None");', ["12", "1", "17", "36", "100"], JN)
jq("j-perfect-number", "Perfect Number", "EASY", T, "A perfect number equals the sum of its proper divisors (6 = 1 + 2 + 3). " + YN, "One positive integer.", "`Yes` or `No`.", "1 <= n <= 100000",
   'int sum = 0;\nfor (int i = 1; i < n; i++) if (n % i == 0) sum += i;\nSystem.out.println(sum == n ? "Yes" : "No");', ["6", "28", "12", "1", "496"], JN)
jq("j-strong-number", "Strong Number", "MEDIUM", T, "A strong number equals the sum of the factorials of its digits (145 = 1! + 4! + 5!). " + YN, "One positive integer.", "`Yes` or `No`.", "1 <= n <= 10^7",
   'int[] fact = new int[10];\nfact[0] = 1;\nfor (int i = 1; i < 10; i++) fact[i] = fact[i - 1] * i;\nint original = n, sum = 0;\nwhile (n > 0) {\n    sum += fact[n % 10];\n    n /= 10;\n}\nSystem.out.println(sum == original ? "Yes" : "No");', ["145", "1", "2", "123", "40585"], JN)
jq("j-neon-number", "Neon Number", "EASY", T, "A number is neon when the digits of its square add up to the number (9 squared is 81, and 8 + 1 = 9). " + YN, "One non-negative integer.", "`Yes` or `No`.", "0 <= n <= 100000",
   'long sq = (long) n * n;\nint sum = 0;\nwhile (sq > 0) {\n    sum += sq % 10;\n    sq /= 10;\n}\nSystem.out.println(sum == n ? "Yes" : "No");', ["9", "0", "1", "10", "45"], JN)
jq("j-spy-number", "Spy Number", "EASY", T, "A spy number has equal sum and product of its digits (1124: sum 8, product 8). " + YN, "One positive integer.", "`Yes` or `No`.", "1 <= n <= 10^9",
   'int sum = 0;\nlong prod = 1;\nwhile (n > 0) {\n    sum += n % 10;\n    prod *= n % 10;\n    n /= 10;\n}\nSystem.out.println(sum == prod ? "Yes" : "No");', ["1124", "123", "22", "7", "1412"], JN)
jq("j-automorphic-number", "Automorphic Number", "MEDIUM", T, "A number is automorphic when its square ends with the number itself (25 squared is 625). " + YN, "One positive integer.", "`Yes` or `No`.", "1 <= n <= 100000",
   'long sq = (long) n * n, p = 1;\nfor (int t = n; t > 0; t /= 10) p *= 10;\nSystem.out.println(sq % p == n ? "Yes" : "No");', ["25", "5", "76", "7", "376"], JN)
jq("j-binary-to-decimal", "Binary to Decimal", "MEDIUM", T, "Read a binary number written with 0s and 1s (up to 18 digits) and print its decimal value with a loop.", "One binary number.", "The decimal value.", "Only digits 0 and 1",
   'long value = 0, power = 1;\nwhile (n > 0) {\n    value += (n % 10) * power;\n    power *= 2;\n    n /= 10;\n}\nSystem.out.println(value);', ["1010", "1", "0", "11111111", "100000"], JL)
jq("j-decimal-to-binary", "Decimal to Binary", "MEDIUM", T, "Print the binary form of `n` (`0` prints `0`) using repeated division by 2.", ONE, "The binary digits.", "0 <= n <= 10^9",
   'StringBuilder sb = new StringBuilder();\ndo {\n    sb.append(n % 2);\n    n /= 2;\n} while (n > 0);\nSystem.out.println(sb.reverse());', ["10", "0", "1", "255", "1000000000"], JN)
jq("j-gcd-three", "GCD of Three Numbers", "EASY", T, "Print the greatest common divisor of three positive integers.", "One line with three integers.", "The GCD.", "1 <= values <= 10^9",
   'while (b != 0) { int t = a % b; a = b; b = t; }\nwhile (c != 0) { int t = a % c; a = c; c = t; }\nSystem.out.println(a);', ["12 18 24", "7 5 3", "100 50 25", "8 8 8", "30 45 60"], [("int", "a b c")])
jq("j-pronic-number", "Pronic Number", "EASY", T, "A pronic number is the product of two consecutive integers (12 = 3 x 4). " + YN, "One non-negative integer.", "`Yes` or `No`.", "0 <= n <= 10^9",
   'boolean found = false;\nfor (long i = 0; i * (i + 1) <= n; i++) if (i * (i + 1) == n) found = true;\nSystem.out.println(found ? "Yes" : "No");', ["12", "0", "2", "10", "56", "99999"], JN)
jq("j-harshad-number", "Harshad Number", "EASY", T, "A Harshad number is divisible by the sum of its digits (18: 1 + 8 = 9). " + YN, "One positive integer.", "`Yes` or `No`.", "1 <= n <= 10^9",
   'int original = n, sum = 0;\nwhile (n > 0) {\n    sum += n % 10;\n    n /= 10;\n}\nSystem.out.println(original % sum == 0 ? "Yes" : "No");', ["18", "19", "21", "12", "1729"], JN)
jq("j-disarium-number", "Disarium Number", "MEDIUM", T, "A number is disarium when its digits raised to their positions add up to it (89 = 8^1 + 9^2). " + YN, "One positive integer.", "`Yes` or `No`.", "1 <= n <= 10^7",
   'int original = n, digits = String.valueOf(n).length();\nlong sum = 0;\nfor (int t = n, pos = digits; t > 0; t /= 10, pos--) sum += (long) Math.pow(t % 10, pos);\nSystem.out.println(sum == original ? "Yes" : "No");', ["89", "135", "175", "100", "518"], JN)
jq("j-emirp-number", "Emirp Number", "MEDIUM", T, "An emirp is a prime whose reversal is a different prime (13 and 31). " + YN, "One positive integer.", "`Yes` or `No`.", "1 <= n <= 10^6",
   'long rev = 0;\nfor (long t = n; t > 0; t /= 10) rev = rev * 10 + t % 10;\nboolean a = n >= 2, b = rev >= 2;\nfor (long i = 2; i * i <= n; i++) if (n % i == 0) { a = false; break; }\nfor (long i = 2; i * i <= rev; i++) if (rev % i == 0) { b = false; break; }\nSystem.out.println(a && b && rev != n ? "Yes" : "No");', ["13", "11", "37", "23", "17"], JN)
jq("j-happy-number", "Happy Number", "MEDIUM", T, "Replace the number by the sum of the squares of its digits again and again. If it reaches 1 it is happy (19: 82, 68, 100, 1). " + YN, "One positive integer.", "`Yes` or `No`.", "1 <= n <= 10^6",
   'int steps = 0;\nwhile (n != 1 && steps < 1000) {\n    int sum = 0;\n    while (n > 0) {\n        sum += (n % 10) * (n % 10);\n        n /= 10;\n    }\n    n = sum;\n    steps++;\n}\nSystem.out.println(n == 1 ? "Yes" : "No");', ["19", "4", "1", "7", "20"], JN)
jq("j-twin-primes", "Twin Primes up to 100", "MEDIUM", T, "Twin primes differ by 2. Print every pair up to 100, one per line, like `(3, 5)`.", "There is no input.", "One pair per line.", "None.",
   'boolean[] prime = new boolean[102];\nfor (int n = 2; n <= 101; n++) {\n    prime[n] = true;\n    for (int i = 2; i * i <= n; i++) if (n % i == 0) { prime[n] = false; break; }\n}\nfor (int n = 2; n + 2 <= 100; n++) if (prime[n] && prime[n + 2]) System.out.println("(" + n + ", " + (n + 2) + ")");', [""], (), samples=1)
jq("j-prime-palindrome", "Prime Palindrome", "MEDIUM", T, "Print `Yes` if the number is both prime and a palindrome, else `No`.", "One positive integer.", "`Yes` or `No`.", "1 <= n <= 10^8",
   'boolean prime = n >= 2;\nfor (long i = 2; i * i <= n; i++) if (n % i == 0) { prime = false; break; }\nlong rev = 0;\nfor (long t = n; t > 0; t /= 10) rev = rev * 10 + t % 10;\nSystem.out.println(prime && rev == n ? "Yes" : "No");', ["131", "13", "121", "2", "10301"], JN)
jq("j-number-guessing", "Number Guessing Game", "MEDIUM", T, "The first number is the secret. The next numbers are guesses, read one by one in a `do-while` loop until one is right. For each wrong guess print `Too low` or `Too high`; at the end print `Correct in <k> guesses`.", "The secret, then at least one guess; the last guess is the correct one.", "One line per wrong guess, then the last line.", "Guesses end with the secret",
   'int guesses = 0, guess;\ndo {\n    guess = in.nextInt();\n    guesses++;\n    if (guess < secret) System.out.println("Too low");\n    else if (guess > secret) System.out.println("Too high");\n} while (guess != secret);\nSystem.out.println("Correct in " + guesses + " guesses");', ["50\n10\n90\n50", "7\n7", "100\n1\n50\n75\n100", "3\n9\n5\n4\n3", "20\n21\n19\n20"], [("int", "secret")])
jq("j-menu-calculator", "Menu-Driven Calculator", "MEDIUM", T, "Repeat in a `do-while` loop: read a choice (1 add, 2 subtract, 3 multiply, 4 divide, 0 exit). For 1 to 4 read two integers and print the result (division is integer division; dividing by zero prints `Cannot divide by zero`). For any other choice print `Invalid choice`. When 0 is read print `Goodbye`.", "Lines of `choice` (and two numbers after 1 to 4), ending with 0.", "One line per command.", "At most 100 commands",
   'int choice;\ndo {\n    choice = in.nextInt();\n    if (choice >= 1 && choice <= 4) {\n        int a = in.nextInt(), b = in.nextInt();\n        if (choice == 1) System.out.println(a + b);\n        else if (choice == 2) System.out.println(a - b);\n        else if (choice == 3) System.out.println((long) a * b);\n        else System.out.println(b == 0 ? "Cannot divide by zero" : String.valueOf(a / b));\n    } else if (choice != 0) System.out.println("Invalid choice");\n} while (choice != 0);\nSystem.out.println("Goodbye");', ["1 2 3\n3 4 5\n0", "4 7 0\n4 9 2\n0", "9\n2 10 4\n0", "0", "1 -5 5\n2 1 1\n3 0 9\n0"], (), scanner=True)
jq("j-average-until-zero", "Average Until Zero", "MEDIUM", T, "Read numbers until a 0 is read (the 0 is not counted). Print their average with two decimals, or `No numbers` if the first number is 0.", "Numbers ending with 0.", "The average or a message.", "At most 1000 numbers",
   'int x, count = 0;\nlong sum = 0;\ndo {\n    x = in.nextInt();\n    if (x != 0) { sum += x; count++; }\n} while (x != 0);\nSystem.out.println(count == 0 ? "No numbers" : String.format("%.2f", (double) sum / count));', ["4 6 8 0", "0", "5 0", "-2 2 7 0", "100 200 300 401 0"], (), scanner=True)
jq("j-largest-among-inputs", "Largest of N Numbers", "EASY", T, "Read `n` and then `n` integers; print the largest.", "First line `n`, then `n` integers.", "The largest.", "1 <= n <= 1000",
   'int max = in.nextInt();\nint i = 1;\nwhile (i < n) {\n    int x = in.nextInt();\n    if (x > max) max = x;\n    i++;\n}\nSystem.out.println(max);', ["4\n3 9 1 7", "1\n5", "3\n-4 -9 -1", "5\n100 50 75 200 10", "2\n2 2"], JN)
jq("j-count-pos-neg", "Count Positive and Negative", "EASY", T, "Read numbers until a 0 is read. Print `Positive: <x>` and `Negative: <y>` (the 0 is not counted).", "Numbers ending with 0.", "Two lines.", "At most 1000 numbers",
   'int x, pos = 0, neg = 0;\ndo {\n    x = in.nextInt();\n    if (x > 0) pos++;\n    else if (x < 0) neg++;\n} while (x != 0);\nSystem.out.println("Positive: " + pos + "\\nNegative: " + neg);', ["4 -2 7 0", "0", "-1 -2 -3 0", "5 5 0", "1 -1 1 -1 0"], (), scanner=True)
jq("j-compound-interest-years", "Compound Interest Year by Year", "MEDIUM", T, "Read the principal, the yearly rate (percent) and the number of years. For each year print `Year <k>: <amount>` (two decimals), where the amount grows by the rate each year.", "One line: `principal rate years`.", "One line per year.", "1 <= years <= 50",
   'double amount = p;\nfor (int y = 1; y <= years; y++) {\n    amount += amount * r / 100;\n    System.out.printf("Year %d: %.2f%n", y, amount);\n}', ["1000 10 3", "5000 5 1", "100 100 4", "250.5 7.5 2", "1 1 5"], [("double", "p r"), ("int", "years")])
jq("j-taylor-sine", "Sine with a Taylor Series", "HARD", T, "Approximate `sin(x)` (x in radians) with `x - x^3/3! + x^5/5! - ...` using `n` terms. Print the result with four decimals.", "One line: `x n`.", "The approximation.", "|x| <= 3, 1 <= n <= 15",
   'double term = x, sum = 0;\nfor (int k = 0; k < n; k++) {\n    sum += term;\n    term = -term * x * x / ((2 * k + 2) * (2 * k + 3));\n}\nSystem.out.printf("%.4f%n", sum);', ["1 5", "0 3", "3.14159 8", "0.5 4", "-1 6"], [("double", "x"), ("int", "n")])
jq("j-babylonian-sqrt", "Square Root, the Babylonian Way", "MEDIUM", T, "Start with a guess of `n / 2` and repeat `guess = (guess + n / guess) / 2` twenty times. Print the guess with four decimals (print `0.0000` for 0).", "One non-negative decimal.", "The square root.", "0 <= n <= 10^6",
   'double guess = n / 2;\nif (n == 0) guess = 0;\nelse for (int i = 0; i < 20; i++) guess = (guess + n / guess) / 2;\nSystem.out.printf("%.4f%n", guess);', ["16", "2", "0", "100", "0.25"], [("double", "n")])
jq("j-digit-frequency", "Count One Digit", "EASY", T, "Read `n` and a digit `d`. Print how many times `d` appears in `n`.", "One line: `n d`.", "The count.", "0 <= n <= 10^12, 0 <= d <= 9",
   'int count = 0;\ndo {\n    if (n % 10 == d) count++;\n    n /= 10;\n} while (n > 0);\nSystem.out.println(count);', ["1232123 2", "1000 0", "0 0", "999 9", "12345 7"], [("long", "n"), ("int", "d")])
jq("j-largest-digit", "Largest Digit", "EASY", T, "Print the largest digit of `n`.", ONE, "The digit.", "0 <= n <= 10^9",
   'int best = 0;\nwhile (n > 0) {\n    best = Math.max(best, n % 10);\n    n /= 10;\n}\nSystem.out.println(best);', ["1234", "0", "9", "1111", "50472"], JN)
jq("j-smallest-digit", "Smallest Digit", "EASY", T, "Print the smallest digit of `n`.", ONE, "The digit.", "0 <= n <= 10^9",
   'int best = 9;\ndo {\n    best = Math.min(best, n % 10);\n    n /= 10;\n} while (n > 0);\nSystem.out.println(best);', ["1234", "0", "9", "5555", "50472"], JN)
jq("j-swap-first-last", "Swap First and Last Digit", "MEDIUM", T, "Swap the first and last digits of `n` and print the new number. A single-digit number stays as it is.", "One positive integer.", "The new number.", "1 <= n <= 10^9",
   'if (n < 10) { System.out.println(n); return; }\nlong p = 1;\nwhile (n / p >= 10) p *= 10;\nlong first = n / p, last = n % 10;\nSystem.out.println(last * p + (n % p) / 10 * 10 + first);', ["1234", "5", "12", "9871", "100005"], JN)
jq("j-strictly-increasing", "Strictly Increasing?", "EASY", T, "Read `n` numbers. Print `Yes` if every number is larger than the one before it, otherwise `No`.", "First line `n`, then `n` integers.", "`Yes` or `No`.", "1 <= n <= 1000",
   'int prev = in.nextInt();\nboolean ok = true;\nint i = 1;\nwhile (i < n) {\n    int x = in.nextInt();\n    if (x <= prev) ok = false;\n    prev = x;\n    i++;\n}\nSystem.out.println(ok ? "Yes" : "No");', ["4\n1 2 3 4", "3\n3 2 1", "1\n5", "3\n1 1 2", "4\n-5 0 3 10"], JN)
jq("j-harmonic-sum", "Harmonic Series", "EASY", T, "Print `1 + 1/2 + 1/3 + ... + 1/n` with four decimals.", ONE, "The sum.", "1 <= n <= 100000",
   'double sum = 0;\nfor (int i = 1; i <= n; i++) sum += 1.0 / i;\nSystem.out.printf("%.4f%n", sum);', ["1", "2", "10", "100", "5"], JN)
jq("j-alternating-sum", "Alternating Sum", "EASY", T, "Print `1 - 2 + 3 - 4 + ...` up to `n` terms.", ONE, "The sum.", "1 <= n <= 100000",
   'long sum = 0;\nfor (int i = 1; i <= n; i++) sum += i % 2 == 1 ? i : -i;\nSystem.out.println(sum);', ["5", "1", "10", "100000", "7"], JN)
jq("j-tribonacci", "Tribonacci Series", "EASY", T, "Each term is the sum of the three before it, starting `0 0 1`. Print the first `n` terms on one line.", ONE, "`n` numbers.", "1 <= n <= 60",
   'long[] t = new long[Math.max(n, 3)];\nt[2] = 1;\nfor (int i = 3; i < n; i++) t[i] = t[i - 1] + t[i - 2] + t[i - 3];\nStringBuilder sb = new StringBuilder();\nfor (int i = 0; i < n; i++) sb.append(t[i]).append(i < n - 1 ? " " : "");\nSystem.out.println(sb);', ["10", "1", "3", "4", "50"], JN)
jq("j-prime-factors", "Prime Factors", "MEDIUM", T, "Print the prime factors of `n` in increasing order on one line, repeating a factor as often as it divides (`12` gives `2 2 3`).", ONE, "The prime factors.", "2 <= n <= 10^9",
   'StringBuilder sb = new StringBuilder();\nfor (long p = 2; p * p <= n; p++) {\n    while (n % p == 0) {\n        sb.append(sb.length() > 0 ? " " : "").append(p);\n        n /= p;\n    }\n}\nif (n > 1) sb.append(sb.length() > 0 ? " " : "").append(n);\nSystem.out.println(sb);', ["12", "2", "97", "360", "999999937"], JL)
jq("j-smith-number", "Smith Number", "HARD", T, "A Smith number is composite and the sum of its digits equals the sum of the digits of all its prime factors counted with repeats (22 = 2 x 11: 2 + 2 = 2 + 1 + 1). " + YN, "One positive integer.", "`Yes` or `No`.", "1 <= n <= 10^6",
   'int original = n, digitSum = 0, factorSum = 0, count = 0;\nfor (int t = n; t > 0; t /= 10) digitSum += t % 10;\nfor (int p = 2; (long) p * p <= n; p++) {\n    while (n % p == 0) {\n        for (int t = p; t > 0; t /= 10) factorSum += t % 10;\n        n /= p;\n        count++;\n    }\n}\nif (n > 1) {\n    for (int t = n; t > 0; t /= 10) factorSum += t % 10;\n    count++;\n}\nSystem.out.println(count > 1 && digitSum == factorSum ? "Yes" : "No");', ["22", "4", "27", "13", "85", "666"], JN)
jq("j-digits-divisible-by-3", "Digits Divisible by 3", "EASY", T, "Count how many digits of `n` are divisible by 3 (0, 3, 6 and 9 all count).", ONE, "The count.", "0 <= n <= 10^9",
   'int count = 0;\ndo {\n    if ((n % 10) % 3 == 0) count++;\n    n /= 10;\n} while (n > 0);\nSystem.out.println(count);', ["12369", "0", "7", "333", "1000"], JN)
jq("j-digital-root", "Digital Root", "MEDIUM", T, "Add the digits of `n` again and again until one digit is left (`9875` gives `29`, then `11`, then `2`). Print that digit.", ONE, "The digital root.", "0 <= n <= 10^9",
   'while (n >= 10) {\n    int sum = 0;\n    while (n > 0) {\n        sum += n % 10;\n        n /= 10;\n    }\n    n = sum;\n}\nSystem.out.println(n);', ["9875", "0", "7", "999999999", "1234"], JN)
jq("j-armstrong-any", "Armstrong Number (any length)", "MEDIUM", T, "Each digit raised to the number of digits must add up to the number (1634 = 1 + 1296 + 81 + 256). " + YN, "One positive integer.", "`Yes` or `No`.", "1 <= n <= 10^7",
   'int original = n, digits = String.valueOf(n).length();\nlong sum = 0;\nwhile (n > 0) {\n    long p = 1;\n    for (int i = 0; i < digits; i++) p *= n % 10;\n    sum += p;\n    n /= 10;\n}\nSystem.out.println(sum == original ? "Yes" : "No");', ["153", "1634", "9474", "123", "8208", "9"], JN)
jq("j-odd-digits-only", "Numbers with Only Odd Digits", "MEDIUM", T, "Print every number from 1 to `n` whose digits are all odd, on one line separated by spaces (print `None` if there is no such number).", ONE, "The numbers or `None`.", "1 <= n <= 10000",
   'StringBuilder sb = new StringBuilder();\nfor (int x = 1; x <= n; x++) {\n    boolean ok = true;\n    for (int t = x; t > 0; t /= 10) if ((t % 10) % 2 == 0) ok = false;\n    if (ok) sb.append(sb.length() > 0 ? " " : "").append(x);\n}\nSystem.out.println(sb.length() > 0 ? sb.toString() : "None");', ["20", "1", "2", "100", "40"], JN)
jq("j-consecutive-duplicate-digits", "Adjacent Equal Digits", "EASY", T, "Print `Yes` if the same digit appears twice next to each other in `n` (like the `22` in `1223`), otherwise `No`.", "One positive integer.", "`Yes` or `No`.", "1 <= n <= 10^9",
   'boolean dup = false;\nint prev = -1;\nwhile (n > 0) {\n    int d = n % 10;\n    if (d == prev) dup = true;\n    prev = d;\n    n /= 10;\n}\nSystem.out.println(dup ? "Yes" : "No");', ["1223", "1234", "7", "11", "1213121"], JN)
jq("j-collatz", "Collatz Sequence", "MEDIUM", T, "Start at `n`. If it is even divide it by 2, otherwise multiply by 3 and add 1; repeat until you reach 1. Print every number on one line, then `Steps: <count>` on the next line.", "One positive integer.", "Two lines.", "1 <= n <= 10^6",
   'long x = n;\nint steps = 0;\nStringBuilder sb = new StringBuilder().append(x);\nwhile (x != 1) {\n    x = x % 2 == 0 ? x / 2 : 3 * x + 1;\n    sb.append(" ").append(x);\n    steps++;\n}\nSystem.out.println(sb);\nSystem.out.println("Steps: " + steps);', ["6", "1", "7", "27", "10"], JN)
jq("j-count-factors", "Count the Factors", "EASY", T, "Print how many positive numbers divide `n` exactly.", "One positive integer.", "The count.", "1 <= n <= 10^6",
   'int count = 0;\nfor (int i = 1; i <= n; i++) if (n % i == 0) count++;\nSystem.out.println(count);', ["12", "1", "17", "36", "720720"], JN)
jq("j-perfect-square", "Perfect Square Without sqrt", "EASY", T, "Print `Yes` if `n` is the square of a whole number, `No` otherwise, without using `Math.sqrt`.", "One non-negative integer.", "`Yes` or `No`.", "0 <= n <= 10^12",
   'boolean square = false;\nfor (long i = 0; i * i <= n; i++) if (i * i == n) square = true;\nSystem.out.println(square ? "Yes" : "No");', ["16", "0", "2", "1000000", "999999999999"], JL)
